package com.aistock.prediction.verification;
import com.aistock.common.BusinessException;import com.fasterxml.jackson.databind.*;import java.time.*;import java.sql.Timestamp;import java.util.*;
import org.springframework.http.HttpStatus;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.DataSourceTransactionManager;import org.springframework.transaction.support.TransactionTemplate;
public final class VerificationRepository {
 public record Claim(VerificationReceipt receipt,JsonNode snapshot,boolean execute){}
 private final JdbcTemplate jdbc;private final ObjectMapper mapper;private final Clock clock;private final TransactionTemplate tx;
 public VerificationRepository(JdbcTemplate jdbc,ObjectMapper mapper,Clock clock){this.jdbc=jdbc;this.mapper=mapper;this.clock=clock;tx=new TransactionTemplate(new DataSourceTransactionManager(Objects.requireNonNull(jdbc.getDataSource())));}
 public Claim begin(UUID prediction,VerificationRequest r,String hash){return begin(prediction,r,hash,clock.instant().plusSeconds(90));}
 public Claim begin(UUID prediction,VerificationRequest r,String hash,Instant deadline){return bounded(deadline,s->{jdbc.update("insert into forecast_verification_head(prediction_id) values(?) on duplicate key update prediction_id=prediction_id",prediction.toString());jdbc.queryForMap("select * from forecast_verification_head where prediction_id=? for update",prediction.toString());var previous=jdbc.queryForList("select * from forecast_verification_operation where operation_id=? for update",r.operationId().toString());if(!previous.isEmpty()){var row=previous.get(0);if(!hash.equals(row.get("request_hash"))||!prediction.toString().equals(row.get("prediction_id")))throw error("VERIFICATION_OPERATION_CONFLICT",HttpStatus.CONFLICT);expire(r.operationId(),row);return new Claim(operation(r.operationId()),null,false);}var snapshots=jdbc.queryForList("select snapshot_json from forecast_request where prediction_id=? and state='SUCCEEDED' and snapshot_json is not null",String.class,prediction.toString());if(snapshots.isEmpty())throw error("VERIFICATION_PREDICTION_INVALID",HttpStatus.CONFLICT);var snapshot=parse(snapshots.get(0));jdbc.update("insert into forecast_verification_operation(operation_id,prediction_id,request_hash,state,due_through,lease_until,created_at) values(?,?,?,'RUNNING',?,?,?)",r.operationId().toString(),prediction.toString(),hash,r.dueThrough(),Timestamp.from(r.leaseUntil()),Timestamp.from(clock.instant()));return new Claim(new VerificationReceipt(r.operationId(),"RUNNING",null,null),snapshot,true);});}
 public VerificationReceipt publish(UUID prediction,VerificationRequest r,JsonNode evidence,VerificationRecords.Result result,String hash){return publish(prediction,r,evidence,result,hash,clock.instant().plusSeconds(90));}
 public VerificationReceipt publish(UUID prediction,VerificationRequest r,JsonNode evidence,VerificationRecords.Result result,String hash,Instant deadline){return publish(prediction,r,evidence,result,hash,deadline,1);}
 public VerificationReceipt publish(UUID prediction,VerificationRequest r,JsonNode evidence,VerificationRecords.Result result,String hash,Instant deadline,long generation){return bounded(deadline,s->{var head=jdbc.queryForMap("select * from forecast_verification_head where prediction_id=? for update",prediction.toString());var operation=jdbc.queryForMap("select * from forecast_verification_operation where operation_id=? for update",r.operationId().toString());checkGeneration(operation,generation);if(!prediction.toString().equals(operation.get("prediction_id")))throw error("VERIFICATION_OPERATION_CONFLICT",HttpStatus.CONFLICT);if(!"RUNNING".equals(operation.get("state")))return receipt(r.operationId(),operation);lease(r);if(!clock.instant().isBefore(com.aistock.prediction.maas.MaasOperationGate.instant(operation.get("lease_until"))))throw error("ATTEMPT_EXPIRED",HttpStatus.CONFLICT);String source=evidence.path("realizationVersionId").asText();var previous=jdbc.queryForList("select version_id from forecast_verification_version where prediction_id=? and realization_version_id=? and rule_version=?",String.class,prediction.toString(),source,VerificationRecords.RULE);String id=previous.isEmpty()?UUID.randomUUID().toString():previous.get(0);if(previous.isEmpty())jdbc.update("insert into forecast_verification_version(version_id,prediction_id,realization_version_id,rule_version,due_through,content_hash,evidence_json,evaluation_json,created_at) values(?,?,?,?,?,?,?,?,?)",id,prediction.toString(),source,VerificationRecords.RULE,r.dueThrough(),hash,json(evidence),json(result),Timestamp.from(clock.instant()));else{var oldHash=jdbc.queryForObject("select content_hash from forecast_verification_version where version_id=?",String.class,id);if(!hash.equals(oldHash))throw error("VERIFICATION_EVIDENCE_CHANGED",HttpStatus.CONFLICT);}
  long sequence=((Number)operation.get("sequence_id")).longValue(),last=((Number)head.get("last_sequence")).longValue();var due=head.get("due_through");LocalDate lastDue=due instanceof java.sql.Date date?date.toLocalDate():due instanceof LocalDate date?date:null;
  if(sequence>=last&&(lastDue==null||!r.dueThrough().isBefore(lastDue)))jdbc.update("update forecast_verification_head set current_version_id=?,due_through=?,last_sequence=? where prediction_id=?",id,r.dueThrough(),sequence,prediction.toString());finishSql(r.operationId(),generation,"AVAILABLE",id,null);lease(r);return new VerificationReceipt(r.operationId(),"AVAILABLE",id,null);});}
 public VerificationReceipt finish(UUID op,String state,String code){return finish(op,1,state,code);}
 public VerificationReceipt finish(UUID op,long generation,String state,String code){if(!Set.of("FAILED","SKIPPED_NOT_DUE").contains(state))throw error("VERIFICATION_OPERATION_CONFLICT",HttpStatus.CONFLICT);return tx.execute(s->{var row=jdbc.queryForMap("select * from forecast_verification_operation where operation_id=? for update",op.toString());checkGeneration(row,generation);if(!"RUNNING".equals(row.get("state")))return receipt(op,row);finishSql(op,generation,state,null,code);return new VerificationReceipt(op,state,null,code);});}
 public VerificationReceipt operation(UUID op){return tx.execute(s->{var rows=jdbc.queryForList("select * from forecast_verification_operation where operation_id=? for update",op.toString());if(rows.isEmpty())throw error("RESOURCE_NOT_FOUND",HttpStatus.NOT_FOUND);expire(op,rows.get(0));return receipt(op,jdbc.queryForMap("select * from forecast_verification_operation where operation_id=?",op.toString()));});}
 public JsonNode current(UUID prediction){var ids=jdbc.queryForList("select current_version_id from forecast_verification_head where prediction_id=? and current_version_id is not null",String.class,prediction.toString());if(ids.isEmpty())throw error("RESOURCE_NOT_FOUND",HttpStatus.NOT_FOUND);var row=jdbc.queryForMap("select * from forecast_verification_version where version_id=?",ids.get(0));var root=mapper.createObjectNode();root.put("verificationVersionId",ids.get(0)).put("realizationVersionId",(String)row.get("realization_version_id")).put("ruleVersion",(String)row.get("rule_version"));root.set("result",parse((String)row.get("evaluation_json")));return root;}
 private <T> T bounded(Instant deadline,java.util.function.Function<org.springframework.transaction.TransactionStatus,T> action){checkBudget(deadline);var limited=new TransactionTemplate(Objects.requireNonNull(tx.getTransactionManager()));limited.setTimeout((int)Math.max(1,Duration.between(clock.instant(),deadline).toSeconds()));return limited.execute(s->{checkBudget(deadline);var value=action.apply(s);checkBudget(deadline);return value;});}
 private void checkBudget(Instant deadline){if(!clock.instant().isBefore(deadline))throw error("VERIFICATION_BUDGET_EXCEEDED",HttpStatus.SERVICE_UNAVAILABLE);}
 private void expire(UUID id,Map<String,Object> row){if("RUNNING".equals(row.get("state"))&&jdbc.queryForObject("select count(*) from forecast_verification_operation where operation_id=? and lease_until<=?",Integer.class,id.toString(),Timestamp.from(clock.instant()))==1)finishSql(id,((Number)row.get("execution_generation")).longValue(),"FAILED",null,"ATTEMPT_EXPIRED");}
 private void finishSql(UUID id,long generation,String state,String version,String error){if(jdbc.update("update forecast_verification_operation set state=?,version_id=?,error_code=?,finished_at=?,fencing_revision=fencing_revision+1 where operation_id=? and execution_generation=? and state='RUNNING'",state,version,error,Timestamp.from(clock.instant()),id.toString(),generation)!=1)throw error("VERIFICATION_OPERATION_CONFLICT",HttpStatus.CONFLICT);}
 private void checkGeneration(Map<String,Object> row,long generation){if(generation<1||((Number)row.get("execution_generation")).longValue()!=generation)throw error("VERIFICATION_OPERATION_CONFLICT",HttpStatus.CONFLICT);}
 public String marketUseInput(UUID operation,long generation){return tx.execute(s->{var row=jdbc.queryForMap("select * from forecast_verification_operation where operation_id=? for update",operation.toString());checkGeneration(row,generation);if(!"RUNNING".equals(row.get("state"))||!clock.instant().isBefore(com.aistock.prediction.maas.MaasOperationGate.instant(row.get("lease_until"))))throw com.aistock.prediction.marketuse.MarketUseClient.unavailable();return jdbc.queryForObject("select instrument_id from forecast_request where prediction_id=?",String.class,row.get("prediction_id"));});}
 public JsonNode executionTerminal(UUID operation,long generation){return tx.execute(s->{var row=jdbc.queryForMap("select * from forecast_verification_operation where operation_id=? for update",operation.toString());checkGeneration(row,generation);expire(operation,row);row=jdbc.queryForMap("select * from forecast_verification_operation where operation_id=?",operation.toString());if(!Set.of("AVAILABLE","FAILED","SKIPPED_NOT_DUE").contains(row.get("state"))||row.get("finished_at")==null||"AVAILABLE".equals(row.get("state"))&&row.get("version_id")==null)throw com.aistock.prediction.marketuse.MarketUseClient.unavailable();return mapper.createObjectNode().put("state","FAILED".equals(row.get("state"))?"FAILED":"SUCCEEDED").put("terminalAt",com.aistock.prediction.maas.MaasOperationGate.instant(row.get("finished_at")).toString()).put("fencingRevision",row.get("fencing_revision").toString()).put("resultIdentity",row.get("version_id")==null?operation.toString():row.get("version_id").toString());});}
 private VerificationReceipt receipt(UUID id,Map<String,Object> row){return new VerificationReceipt(id,(String)row.get("state"),(String)row.get("version_id"),(String)row.get("error_code"));}
 private void lease(VerificationRequest r){if(!clock.instant().isBefore(r.leaseUntil()))throw error("ATTEMPT_EXPIRED",HttpStatus.CONFLICT);}
 private JsonNode parse(String value){try{return mapper.readTree(value);}catch(Exception e){throw error("VERIFICATION_RECORD_INVALID",HttpStatus.INTERNAL_SERVER_ERROR);}}
 private String json(Object value){try{return mapper.writeValueAsString(value);}catch(Exception e){throw error("VERIFICATION_RECORD_INVALID",HttpStatus.INTERNAL_SERVER_ERROR);}}
 static BusinessException error(String code,HttpStatus status){return new BusinessException(code,"预测验证暂未完成，已有预测与验证保留",status);}
}
